import{_ as t,H as r,f as e,i as a}from"./chunks/framework.DLd0CbzH.js";const d=JSON.parse('{"title":"Сырьё (Склад материалов)","description":"Как работает партионный учет, логистика и MAC-себестоимость сырья в ОмниКрафт ЕРП.","frontmatter":{"title":"Сырьё (Склад материалов)","description":"Как работает партионный учет, логистика и MAC-себестоимость сырья в ОмниКрафт ЕРП.","order":5},"headers":[],"relativePath":"ru/docs/spaces/production/warehouse.md","filePath":"ru/docs/spaces/production/warehouse.md"}'),s={name:"ru/docs/spaces/production/warehouse.md"};function l(i,o,n,p,c,u){return r(),e("div",null,[...o[0]||(o[0]=[a('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="📦-сырье-склад-материалов-и-партионные-закупки" tabindex="-1">📦 Сырьё: Склад материалов и партионные закупки <a class="header-anchor" href="#📦-сырье-склад-материалов-и-партионные-закупки" aria-label="Permalink to &quot;📦 Сырьё: Склад материалов и партионные закупки&quot;">​</a></h1><p>Вкладка <strong>«Сырьё»</strong> — это сердце логистики вашего ремесленного дела. Здесь хранятся все материалы, которые физически участвуют в производстве изделий: кожа, нитки, клей, фурнитура, ткань, древесина и упаковка.</p><p>ОмниКрафт ЕРП использует профессиональный метод учета себестоимости — <strong>MAC (Moving Average Cost — Скользящая средняя стоимость)</strong>, избавляя вас от необходимости вручную высчитывать, сколько стоит квадратный дециметр кожи с учетом стоимости доставки.</p><hr><h2 id="📋-паспорт-материала" tabindex="-1">📋 Паспорт материала <a class="header-anchor" href="#📋-паспорт-материала" aria-label="Permalink to &quot;📋 Паспорт материала&quot;">​</a></h2><p>Прежде чем купить материал, его нужно добавить в базу (номенклатуру). Нажмите кнопку <strong>«+»</strong> (Новая позиция) в верхней панели.</p><p>В паспорте материала указываются:</p><ul><li><strong>Название:</strong> Например, <em>«Кожа Buttero (Коньяк)»</em>.</li><li><strong>Категория:</strong> Группировка для удобства (например, <em>«Натуральная кожа»</em>, <em>«Нитки»</em>, <em>«Фурнитура»</em>). Категории можно редактировать &quot;на лету&quot;, нажав на иконку карандаша.</li><li><strong>Единицы измерения:</strong> В чем вы будете измерять материал в рецептах (дм², шт, мл, метры). <em>Важно: выбирайте ту единицу, в которой вам удобнее считать расход на одно изделие.</em></li></ul><blockquote><p><strong>Привязка поставщиков и ссылок</strong> Если вы нажмете на иконку карандаша ✏️ рядом с уже добавленным материалом, откроется расширенный паспорт. Там вы сможете привязать к материалу конкретных поставщиков (например, <em>«Тавро»</em>, <em>«Магазин у дома»</em>) и сохранить прямые веб-ссылки на карточки товаров, чтобы в будущем заказывать их в один клик.</p></blockquote><hr><h2 id="🛒-партионная-закупка-и-логистика" tabindex="-1">🛒 Партионная закупка и логистика <a class="header-anchor" href="#🛒-партионная-закупка-и-логистика" aria-label="Permalink to &quot;🛒 Партионная закупка и логистика&quot;">​</a></h2><p>Главная «магия» ОмниКрафт ЕРП кроется в кнопке <strong>«Партионная закупка»</strong> (иконка корзины в верхнем меню). Никогда не вносите купленные материалы через инвентаризацию — используйте закупку!</p><h3 id="как-работает-умное-распределение-доставки" tabindex="-1">Как работает умное распределение доставки: <a class="header-anchor" href="#как-работает-умное-распределение-доставки" aria-label="Permalink to &quot;Как работает умное распределение доставки:&quot;">​</a></h3><p>Допустим, вы заказали у поставщика:</p><ol><li>Кусок кожи за 5 000 ₽</li><li>Набор пряжек за 1 000 ₽</li><li>И заплатили за доставку транспортной компании 600 ₽.</li></ol><p>Если вы просто разделите 600 ₽ доставки пополам (по 300 ₽ на позицию), себестоимость дешевых пряжек взлетит до небес, что сильно исказит цену готовых изделий.</p><p><strong>ОмниКрафт ЕРП распределяет доставку пропорционально стоимости товаров:</strong></p><ul><li>Кожа (5000 ₽) заберет на себя 500 ₽ доставки.</li><li>Пряжки (1000 ₽) заберут всего 100 ₽ доставки. Программа сделает эту математику за доли секунды и запишет на склад правильную, справедливую себестоимость каждой позиции.</li></ul><h3 id="что-происходит-при-проведении-закупки" tabindex="-1">Что происходит при проведении закупки: <a class="header-anchor" href="#что-происходит-при-проведении-закупки" aria-label="Permalink to &quot;Что происходит при проведении закупки:&quot;">​</a></h3><ol><li>На склад зачисляется физическое количество материалов.</li><li>Программа пересчитывает <strong>MAC-цену</strong>. Если у вас оставался кусок кожи по старой цене, а вы купили новый кусок по более дорогой, программа автоматически усреднит их стоимость.</li><li>В журнале <strong>ДДС</strong> автоматически создаются две записи расходов: <em>«Закупка сырья»</em> (на 6 000 ₽) и <em>«Доставка сырья»</em> (на 600 ₽).</li></ol><hr><h2 id="⚖️-инвентаризация-корректировка-остатков" tabindex="-1">⚖️ Инвентаризация (Корректировка остатков) <a class="header-anchor" href="#⚖️-инвентаризация-корректировка-остатков" aria-label="Permalink to &quot;⚖️ Инвентаризация (Корректировка остатков)&quot;">​</a></h2><p>Кнопка <strong>«Инвентаризация»</strong> (иконка весов) используется <strong>только</strong> для исправления физических расхождений на складе.</p><p>Например, программа показывает, что у вас осталось 15 дм² кожи, а по факту — обрезки, из которых уже ничего не сшить. Вы проводите инвентаризацию и списываете недостачу.</p><ul><li><strong>Финансовая безопасность:</strong> Инвентаризация <strong>НЕ трогает</strong> ваши деньги (ДДС) и Баланс. Она лишь списывает физическое количество, чтобы программа не позволяла вам планировать производство из несуществующих материалов.</li></ul><hr><h2 id="🗄️-архивирование-и-удаление" tabindex="-1">🗄️ Архивирование и удаление <a class="header-anchor" href="#🗄️-архивирование-и-удаление" aria-label="Permalink to &quot;🗄️ Архивирование и удаление&quot;">​</a></h2><p>Если вы перестали работать с определенным материалом (например, поставщик перестал привозить эту краску), вы можете отправить его в <strong>Архив</strong> (красная кнопка с коробкой).</p><ul><li>Материал исчезнет из активного списка и перестанет мешаться при поиске.</li><li>При переносе в архив программа предложит <strong>обнулить остатки</strong> этого материала, если они там были.</li><li>Заархивированный материал можно вернуть в любой момент, перейдя на вкладку «В архиве».</li></ul><div class="warning custom-block"><p class="custom-block-title">Блокировка архивации</p><p>Вы не сможете отправить материал в архив, если он прямо сейчас используется хотя бы в одном рецепте (в Калькуляторе) или если на верстаке есть незаконченный заказ, требующий этот материал. Программа выведет окно с точным списком изделий, которые блокируют перенос. Сперва нужно будет изменить рецепты.</p></div>',31)])])}const g=t(s,[["render",l]]);export{d as __pageData,g as default};
